-- GENERATED by `wfi generate` from data/quest/quest-0006.jsonl. Do not edit: `wfi validate` regenerates and diffs it.
local _, WFI = ...
WFI.Data.add("quest", {
  [6001] = { "Corpo e cuore", "Usa la Cenarion Moondust sulla Moonkin Stone di Auberdine per far comparire Lunaclaw. Poi dovrai affrontare Lunaclaw e conquistare la forza del corpo e del cuore che possiede.\n\nQuando hai finito, parla con Mathrengyl Bearwalker, a Darnassus.", "Proprio a est di Auberdine ci sono molte caverne dei moonkin. In quella più vicina ad Auberdine c'è una Moonkin Stone. Lunaclaw, il difensore della pietra, ti affronterà solo quando ci verrà sparsa sopra la Cenarion Moondust. Lunaclaw ha dentro di sé una forza che devi usare come membro dell'artiglio.\n\nTi sei <guadagnato/guadagnata> il diritto di usare questa Cenarion Moondust, {name}... ora dimostrami di esserti <guadagnato/guadagnata> il diritto di possedere la forza del corpo e la forza del cuore che servono a un druido!", "Quando avrai affrontato la sfida che ti attende, capirai fino in fondo la forza del corpo e la forza del cuore. Fino ad allora, non posso aiutarti oltre.", "Hai finalmente fatto il tuo grande passo in un mondo molto più grande, {name}. Sento in te l'insegnamento del Great Bear Spirit, e sento che hai ricevuto la forza che possedeva Lunaclaw.\n\nNon ci sono più ostacoli sulla tua strada... lascia che ora ti insegni cosa vuol dire essere un Druid of the Claw!", 0x9109866f, 0xe7d92ce2, 0xd25471ff, 0xf431a09c, 0x5233b46d, "....." },
  [6002] = { "Corpo e cuore", nil, nil, "Quando avrai affrontato la sfida che ti attende, capirai fino in fondo la forza del corpo e la forza del cuore. Fino ad allora, non posso aiutarti oltre.", "Hai finalmente fatto il tuo grande passo in un mondo molto più grande, {name}. Sento in te l'insegnamento del Great Bear Spirit, e sento che hai ricevuto la forza che possedeva Lunaclaw.\n\nNon ci sono più ostacoli sulla tua strada... lascia che ora ti insegni cosa vuol dire essere un Druid of the Claw!", 0x9109866f, nil, nil, 0xf431a09c, 0x5233b46d, ".mm.." },
  [6027] = { nil, "Prendi il Book of the Ancients e riportalo ad Azore Aldamort, alla torre di Ethel Rethor.", "{name}, ti affido la Gem of the Serpent. Poni questa gemma sulla mano della Serpent Statue, sulla Ranazjar Isle, un'isoletta a nord-ovest di qui. Ponendola, evocherai colui che protegge il Book of the Ancients. Questo libro contiene i segreti dei naga, segreti custoditi da secoli. Portami questo libro e impareremo molto sui nostri nemici squamati!", "Ah, {name}! Che piacere rivederti. Hai il Book of the Ancients?", "Il Book of the Ancients, perduto da tanto tempo! Farò in modo che questo libro venga consegnato all'alto consiglio. Oggi hai fatto bene, e per questo meriti di essere <ringraziato/ringraziata>... come si ringrazia <un/una> <eroe/eroina>!", nil, 0x9ded0f2e, 0x0b6c3f2d, 0xb011a969, 0xf911986b, "m...." },
  [6061] = { "Domare la bestia", nil, nil, nil, nil, 0xecd97a9a, nil, nil, nil, nil, ".mmmm" },
  [6062] = { "Domare la bestia", nil, nil, nil, nil, 0xecd97a9a, nil, nil, nil, nil, ".mmmm" },
  [6063] = { "Domare la bestia", "Usa la Taming Rod per domare un Webwood Lurker. Esercitati, poi riporta la Taming Rod a Dazalar, a Dolanaar.", "Da cacciatore, è importante ricordare la responsabilità che hai tra le mani. La natura non è un potere che si può piegare ai nostri desideri; va rispettata e riconosciuta come qualcosa di più forte della tua stessa esistenza.\n\n{name}, devi dimostrare di averlo capito prima di ottenere la capacità di domare un animale come compagno.\n\nIl tuo primo compito è prendere questa Taming Rod. Con essa potrai domare un webwood lurker. Domalo ed esercita le tue abilità di cacciatore.", "Imparerai, {name}, e un giorno sarai <un/una> grande <cacciatore/cacciatrice>.", "Eccellente, {name}! Impari davvero in fretta.", 0xecd97a9a, 0x72db5042, 0x39ad25e9, 0x407acae4, 0x7f1a8496, "....." },
  [6064] = { "Domare la bestia", "Usa la Taming Rod per addomesticare un Large Crag Boar. Esercita le tue capacità, poi riporta la Taming Rod a Grif Wildheart, a Kharanos.", "Salve, <ragazzo/ragazza>! Allora, vorresti sapere come avere un animale tutto tuo?\n\nBene, cominciamo. Non c'è niente di più importante dell'equipaggiamento quando si va a caccia, ma del mio nuovo Shrapnel Blaster possiamo parlare un'altra volta. Per ora concentriamoci su qualcosa che di sicuro ti interessa molto: un animale!\n\nIl modo migliore per imparare è provare diverse creature come compagni e vedere cosa ti piace. Quindi trova un large crag boar e usa la taming rod per addomesticarlo.", "Non preoccuparti, ragazza! Potrai provarne qualcuno prima di doverne scegliere uno solo.", "Lo so, lo so; ti stai chiedendo cosa viene dopo, vero?!", 0xecd97a9a, 0x19250c04, 0x4bb3619f, 0x2a062314, 0x7fe27a35, ".....", nil, nil, 0x1065c71d, nil, nil },
  [6065] = { "La via del cacciatore", nil, nil, nil, nil, 0xe59cef47, nil, nil, nil, nil, ".mmmm" },
  [6066] = { "La via del cacciatore", nil, nil, nil, nil, 0xe59cef47, nil, nil, nil, nil, ".mmmm" },
  [6067] = { "La via del cacciatore", nil, nil, nil, nil, 0xe59cef47, nil, nil, nil, nil, ".mmmm" },
  [6068] = { "La via del cacciatore", nil, nil, nil, nil, 0xe59cef47, nil, nil, nil, nil, ".mmmm" },
  [6069] = { "La via del cacciatore", nil, nil, nil, nil, 0xe59cef47, nil, nil, nil, nil, ".mmmm" },
  [6070] = { "La via del cacciatore", nil, nil, nil, nil, 0xe59cef47, nil, nil, nil, nil, ".mmmm" },
  [6071] = { "La via del cacciatore", "Parla con Dazalar, a Dolanaar.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Dazalar, a Dolanaar. Lui può metterti sulla strada per guadagnarti un animale tutto tuo.", nil, "Sì, è il momento, {class}.", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0xca92f25f, "...m." },
  [6072] = { "La via del cacciatore", "Parla con Dazalar, a Dolanaar.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Dazalar, a Dolanaar. Lui può metterti sulla strada per guadagnarti un animale tutto tuo.", nil, "Sì, credo che sia il momento...", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0x467a6a72, "...m." },
  [6073] = { "La via del cacciatore", "Parla con Dazalar, a Dolanaar.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Dazalar, a Dolanaar. Lui può metterti sulla strada per guadagnarti un animale tutto tuo.", nil, "Sì, è il momento, {class}.", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0xca92f25f, "...m." },
  [6074] = { "La via del cacciatore", "Parla con Grif Wildheart, a Kharanos.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Grif Wildheart, a Kharanos. Può metterti sulla strada per ottenere un animale tutto tuo.", nil, "Sì, credo proprio che anche tu sia <pronto/pronta>....", 0xe59cef47, 0x7378e497, 0x892ec4fe, nil, 0xc84c7dad, "...m." },
  [6075] = { "La via del cacciatore", "Parla con Grif Wildheart, a Kharanos.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Grif Wildheart, a Kharanos. Può metterti sulla strada per ottenere un animale tutto tuo.", nil, "Sì, credo proprio che anche tu sia <pronto/pronta>....", 0xe59cef47, 0x7378e497, 0x892ec4fe, nil, 0xc84c7dad, "...m." },
  [6076] = { "La via del cacciatore", "Parla con Grif Wildheart, a Kharanos.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Grif Wildheart, a Kharanos. Può metterti sulla strada per ottenere un animale tutto tuo.", nil, "Sì, credo proprio che anche tu sia <pronto/pronta>....", 0xe59cef47, 0x7378e497, 0x892ec4fe, nil, 0xc84c7dad, "...m." },
  [6081] = { "Addestrare la bestia", nil, nil, nil, nil, 0xdbeedc0e, nil, nil, nil, nil, ".mmmm" },
  [6082] = { "Domare la bestia", nil, nil, nil, nil, 0xecd97a9a, nil, nil, nil, nil, ".mmmm" },
  [6083] = { "Domare la bestia", nil, nil, nil, nil, 0xecd97a9a, nil, nil, nil, nil, ".mmmm" },
  [6084] = { "Domare la bestia", "Usa la Taming Rod per addomesticare uno Snow Leopard. Esercita le tue capacità, poi torna da Grif Wildheart, a Kharanos.", "Quei crag boar sono piuttosto massicci; forse vorresti qualcosa con un po' più di finezza? Bene allora, ho proprio quel che fa per te. A sud-est di qui troverai dei grandi felini bianchi chiamati snow leopard. Proprio come un fucile elegantemente intagliato, dietro il loro bell'aspetto si nasconde un combattente potente, capace di infliggere danni enormi. Li troverai molto più agili e veloci del cinghiale che hai addomesticato.\n\nPrendi questa taming rod e vedi come ti trovi con lo snow leopard.", "Cosa ne pensi dello snow leopard, {name}?", "Quando sentirò che hai imparato abbastanza, ti concederò la capacità di scegliere qualsiasi animale ti piaccia.", 0xecd97a9a, 0x71c04a53, 0x18410c9d, 0x00a7c273, 0xa900ecfd, "....." },
  [6085] = { "Domare la bestia", "Usa la Taming Rod per addomesticare un Ice Claw Bear. Esercita le tue capacità, poi riporta la Taming Rod a Grif Wildheart, a Kharanos.", "Forse ti piacerebbe una creatura dotata soprattutto di forza bruta. L'ice claw bear è un ottimo compagno per chi è alle prime armi come cacciatore, come te, e si trova a est di Kharanos. Ecco la taming rod: prova questo animale come compagno e vedi se ti piace!\n\nQuando tornerai, ti darò le capacità necessarie per addomesticare un animale a tua scelta; questa creatura affronterà le sfide che affronti tu e acquisirà esperienza al tuo fianco. Ti mostrerò anche come richiamarlo e congedarlo come preferisci.", "Hai già addomesticato l'ice claw bear?", "Ecco qua, {name}. Ora ti darò il potere di addomesticare una bestia, e di richiamarla e congedarla come preferisci.\n\nTrovati un buon animale fedele, e goditi la caccia!", 0xecd97a9a, 0xe2aae2d4, 0x732759ee, 0x687f27e9, 0x427d0b77, "....." },
  [6086] = { "Addestrare la bestia", "Parla con Belia Thundergranite, a Ironforge.", "{name}, ora hai il potere di addomesticare un animale, ma devi anche acquisire le capacità per addestrarlo.\n\nRecati a Ironforge e trova la Hall of Arms. Lì devi parlare con una delle nostre addestratrici di animali più rispettate, Belia Thundergranite. Ti darà il potere di addestrare il tuo nuovo animale, quindi muoviti, <ragazzo/ragazza>!\n\nBelia è una tipa cordiale; non dovresti avere problemi a ottenere la sua approvazione. Buona fortuna, {name}.", nil, "Una nuova recluta, eh? Vedo che sei sulla strada per diventare {class} di grande valore.\n\nSì, posso concederti le capacità necessarie per addestrare e guidare il tuo animale. Non solo potrai insegnargli nuove abilità, ma ora potrai anche nutrirlo e rianimarlo, se dovesse cadere in battaglia.\n\nRicorda che la chiave per ottenere il meglio dal tuo nuovo animale è rispettarlo e trattarlo bene. In cambio, sarà il tuo amico più fedele.", 0xdbeedc0e, 0x4c05bef3, 0x77988ad7, nil, 0x760bb7bd, "...m.", nil, nil, 0xf137678c, nil, nil },
  [6087] = { "Domare la bestia", nil, nil, nil, nil, 0xecd97a9a, nil, nil, nil, nil, ".mmmm" },
  [6088] = { "Domare la bestia", nil, nil, nil, nil, 0xecd97a9a, nil, nil, nil, nil, ".mmmm" },
  [6089] = { "Addestrare la bestia", nil, nil, nil, nil, 0xdbeedc0e, nil, nil, nil, nil, ".mmmm" },
  [6101] = { "Domare la bestia", "Usa la Taming Rod per domare un Nightsaber Stalker. Esercitati, poi riporta la Taming Rod a Dazalar, a Dolanaar.", "Sulla varietà della natura si può contare, {name}. È prevedibile nel senso che non resta mai uguale: cambia sempre.\n\nI compiti che ti affido ti aiuteranno a vedere e apprezzare le grandi differenze tra le creature che potresti scegliere come compagne.\n\nPrendi questa Taming Rod e usala per domare un nightsaber stalker, che trovi a sud. Esercita le tue abilità di cacciatore. Allora comincerai a capire le somiglianze e le differenze della natura.", "Capire l'equilibrio tra la natura e se stessi è uno stile di vita per ogni elfo della notte.", "Vedo il tuo impegno, e vedo che hai capito quello che ti ho insegnato, {name}.", 0xecd97a9a, 0xd54ea322, 0x4cf39634, 0x2bb052d9, 0xe3639023, "....." },
  [6102] = { "Domare la bestia", "Usa la Taming Rod per domare uno Strigid Screecher. Esercitati, poi riporta la Taming Rod a Dazalar, a Dolanaar.", "Hai domato due creature che abitano la terra, ora devi domarne una che solca i cieli. Usa la Taming Rod per domare uno strigid screecher, che trovi a ovest di qui. Esercita le tue abilità con questo possente gufo al tuo fianco.\n\nQuando tornerai, ti darò le abilità che ti serviranno per domare un animale a tua scelta come compagno; questa creatura affronterà le tue stesse sfide e acquisirà esperienza insieme a te. Ti mostrerò anche come chiamarla e congedarla quando vuoi.", "Sono fiero dei tuoi risultati, {name}. Hai finito l'ultimo compito che ti ho dato?", "Hai imparato tutto quello che potevo insegnarti, {name}. Lascia che ti dia un ultimo consiglio: scegli con giudizio il tuo primo animale. Sceglierai una creatura della terra, dell'acqua o del cielo? Qualunque sia, il tuo animale resterà con te per parecchio tempo, senza dubbio.\n\nEcco, {name}. Ora ti darò il potere di domare una bestia, e di chiamarla e congedarla come ritieni meglio. Usa con orgoglio le tue nuove abilità; te le sei guadagnate.", 0xecd97a9a, 0xe53bb451, 0x3445b668, 0xc9470946, 0xdeb475c1, "....." },
  [6103] = { "Addestrare la bestia", "Parla con Jocaste, nel Cenarion Enclave, a Darnassus.", "Ora hai il potere di domare un animale, ma devi anche acquisire le abilità per addestrarlo.\n\nVai a Darnassus. Lì devi parlare con una delle nostre cacciatrici più venerate, Jocaste. Ti darà la capacità di addestrare il tuo nuovo animale, quindi sbrigati.\n\nJocaste può sembrare severa, ma è sempre contenta di vedere un altro cacciatore salire di grado. Trattala con rispetto e lei ti ricambierà. Buona fortuna, {name}.", nil, "<Un/Una> <cacciatore/cacciatrice> alle prime armi, vedo. Sì, posso darti le abilità che ti servono per addestrare e guidare il tuo animale. Non solo potrai insegnargli nuove abilità, ma ora potrai anche nutrirlo e rianimarlo, se dovesse cadere in battaglia.\n\nRicorda, {name}: rispetta sempre l'equilibrio e vivi in ammirazione della natura che ti circonda. Ora vai. Ci parleremo di nuovo, più avanti.", 0xdbeedc0e, 0x6e901431, 0x3d135ae6, nil, 0xce7253c1, "...m." },
  [6121] = { "Nuove lezioni", "Vai a Moonglade e parla con Dendrite Starblaze nel villaggio di Nighthaven.", "Ora sei <pronto/pronta> a imparare cosa sono i veleni e il potere che noi druidi abbiamo su di essi, {name}. Cenarius ci ha concesso la capacità di eliminare anche i veleni più immondi con un semplice incantesimo. Questo dono non va preso alla leggera... e perché tu impari bene la lezione, affronterai gli effetti degli avvelenamenti come farebbe una persona qualunque.\n\nVai a Moonglade e parla con Dendrite Starblaze; aspetta il tuo arrivo per cominciare la lezione.", nil, "Salute, giovane druido, sono felice di vederti <pronto/pronta> e <desideroso/desiderosa> di imparare a curare i veleni.\n\nIn passato quasi tutti i druidi venivano sottoposti a prove preparate in anticipo, ma per te non sarà così. Ad Auberdine c'è stata un'ondata di avvelenamenti di animali, e il villaggio non è riuscito a curarli. Per questo un loro rappresentante ha chiesto aiuto a Moonglade, e noi mandiamo te ad aiutarli. Non è un esercizio: il lavoro che farai è del tutto reale. Tienilo a mente.", 0xe3814355, 0xb25e3d68, 0x738324f8, nil, 0xe3b1d128, "...m." },
  [6122] = { "La fonte principale", "Usa l'Empty Cliffspring Falls Sampler per prelevare un campione d'acqua all'imboccatura della grotta presso le cascate.\n\nConsegna il Filled Cliffspring Falls Sampler ad Alanndarian Nightsong, ad Auberdine, Darkshore.", "Le Cliffspring Falls di Darkshore sono la fonte principale di acqua potabile della regione, e ora sospetto che siano anche la fonte principale del veleno che danneggia la fauna locale, i cervi in particolare. Usa questo campionatore per prelevare un po' d'acqua all'imboccatura della grotta; fa' attenzione, perché ora pericolosi naga abitano una grotta presso le cascate.\n\nUna volta pieno, consegnalo ad Alanndarian Nightsong, ad Auberdine. È lei che ha chiesto il nostro aiuto, e lavorerai con lei per affrontare questo male.", "Sei tu la persona che ha mandato il Cenarion Circle di Moonglade? Magnifico! Qui abbiamo una bella crisi tra le mani riguardo ai poveri cervi, e siamo felici di ogni aiuto possibile.\n\nHai il campione d'acqua che Dendrite Starblaze ha detto che avresti avuto? Mi ha avvisato che ne avresti prelevato uno perché potessimo lavorare insieme a una cura...", "Per Elune, quest'acqua è disgustosa! Non c'è da stupirsi che i cervi siano malati.\n\nQualcosa inquina l'acqua e, di conseguenza, corrompe l'intera falda di Darkshore. Cervi malati sono stati visti in tutta la zona, e non solo vicino al fiume. Anche se quest'acqua è molto probabilmente una fonte primaria della malattia che si diffonde, c'è qualcos'altro all'opera qui.\n\nQuest'acqua, che tu ci creda o no, ci aiuterà a preparare una cura. Mentre la studio, mi servono alcuni oggetti per formularla...", 0xfe91905d, 0xed0bc128, 0xe6b38f20, 0x7f300676, 0xc7a9f8eb, "....." },
  [6123] = { "Raccogliere la cura", "Porta 5 Earthroot e 12 Lunar Funguses ad Alanndarian Nightsong, ad Auberdine, perché possa preparare un unguento curativo.", "L'acqua farà da base all'unguento curativo che preparerò per i cervi. Per le proprietà curative mi serve dell'earthroot. Gli erboristi sanno come trovarla, quindi se siamo sfortunati e tu non lo sei, dovrai trovarne uno che ci aiuti.\n\nInfine, per la potenza, mi serve del lunar fungus. Trovare le fioriture di lunar fungus è abbastanza facile: sono dappertutto nelle caverne appena a est di qui. Nelle caverne vivono i moonkin, e ultimamente sono irritabili, quindi stai <attento/attenta>.", "Hai i reagenti che mi servono per preparare l'unguento? I cervi non migliorano da soli, quindi è meglio sbrigarsi ad aiutarli!", "Ottimo, {name}, tanto che dovrebbe bastare a preparare dosi abbondanti dell'unguento, almeno abbastanza da cominciare a fare la differenza.\n\nPreparare una cura per i veleni a volte può essere piuttosto difficile, perché ognuno richiede spesso un antidoto molto specifico per contrastarlo. Immagina di poter curare un veleno a piacimento senza doverti preoccupare degli ingredienti esatti dell'antidoto!\n\nOra lasciami mettere al lavoro!", 0xc0a4b4dc, 0x14a92d63, 0xd43adcc8, 0xd5399fb4, 0x0d585714, "....." },
  [6124] = { "Curare i malati", "Usa il Curative Animal Salve su 10 Sickly Deer sparsi per Darkshore; così dovresti curarli. I Sickly Deer sono stati avvistati a partire da sud del Cliffspring River, a nord di Auberdine, fino alla parte meridionale di Darkshore, dove comincia Ashenvale.", "L'unguento ricavato dai reagenti che mi hai portato basta per dieci dosi, {name}. Mentre lavoro con il villaggio per prepararne dell'altro, vorrei che ci aiutassi a portarci avanti. In tutta Darkshore ci sono cervi malati; usa l'unguento su di loro e cura il loro malessere.\n\nDi sicuro Dendrite Starblaze, a Moonglade, vorrà parlarti quando avrai finito. Ti prego, porta i ringraziamenti di Auberdine al Cenarion Circle laggiù... e lascia che ti ringrazi io stessa per l'aiuto che ci hai dato!", "Hai portato a termine ciò che ti ha chiesto Alanndarian Nightsong di Auberdine? Il tuo lavoro non è concluso finché non l'avrai fatto.", "Hai fatto bene a curare i cervi malati di Darkshore; sono vittime inconsapevoli di una contaminazione e di una corruzione più grandi che si stanno diffondendo in tutta la terra. A Darnassus c'è chi sceglie di riconoscere questa minaccia... e chi ignora i segnali crescenti. Spero che tu non sia tra quelli che si mettono i paraocchi davanti ai fatti evidenti, {name}.\n\nAd ogni modo, hai dimostrato il tuo valore come <amico/amica> della natura e del Circle: prendi questo come simbolo.", 0x0116fddd, 0x20fba3fe, 0xbc2e713b, 0xb12ec810, 0x848c8bee, "....." },
  [6125] = { "Potere sul veleno", "Torna da Mathrengyl Bearwalker, nel Cenarion Enclave, a Darnassus.", "Hai imparato cosa significa curare un veleno senza il beneficio dell'aiuto spirituale. Ricorda ciò che altri devono sopportare nel combattere le afflizioni velenose, mentre presto abbraccerai il tuo nuovo potere sul veleno.\n\nOra dovresti tornare da Mathrengyl Bearwalker, a Darnassus, {name}. Senza dubbio ha un incantesimo molto importante da insegnarti, ora che l'allievo ha compreso la lezione che <gli/le> è stata impartita.\n\nAddio, giovane <druido/druida>. Ci parleremo di nuovo.", nil, "<Bentornato/Bentornata>. Ho seguito i tuoi progressi in questa lezione da quando sei <partito/partita>, e devo ammettere che sono rimasto sorpreso nell'apprendere della situazione ad Auberdine. Merita ulteriori indagini, perché l'introduzione di simili veleni nell'ambiente turba moltissimo l'equilibrio.\n\nTi sei <comportato/comportata> con grazia sotto pressione. Per questo non trovo modo migliore di ricompensarti che con un potere permanente sul veleno. Usalo bene, {name}... usalo bene.", 0xfaefb521, 0x6562a80b, 0xe76f8205, nil, 0x02ded2c7, "...m.", nil, nil, 0xe5d51b88, nil, nil },
  [6126] = { "Nuove lezioni", "Vai a Moonglade e parla con Dendrite Starblaze nel villaggio di Nighthaven.", "Ora sei <pronto/pronta> a imparare cosa sono i veleni e il potere che noi druidi abbiamo su di essi, {name}. Cenarius ci ha concesso la capacità di eliminare anche i veleni più immondi con un semplice incantesimo. Questo dono non va preso alla leggera... e perché tu impari bene la lezione, affronterai gli effetti degli avvelenamenti come farebbe una persona qualunque.\n\nVai a Moonglade e parla con Dendrite Starblaze; aspetta il tuo arrivo per cominciare la lezione.", nil, nil, 0xe3814355, 0xb25e3d68, 0x738324f8, nil, nil, "...mm" },
  [6127] = { "La fonte principale", nil, nil, nil, nil, 0xfe91905d, nil, nil, nil, nil, ".mmmm" },
  [6128] = { "Raccogliere la cura", nil, nil, nil, "Ottimo, {name}, tanto che dovrebbe bastare a preparare dosi abbondanti dell'unguento, almeno abbastanza da cominciare a fare la differenza.\n\nPreparare una cura per i veleni a volte può essere piuttosto difficile, perché ognuno richiede spesso un antidoto molto specifico per contrastarlo. Immagina di poter curare un veleno a piacimento senza doverti preoccupare degli ingredienti esatti dell'antidoto!\n\nOra lasciami mettere al lavoro!", 0xc0a4b4dc, nil, nil, nil, 0x0d585714, ".mmm." },
  [6129] = { "Curare i malati", nil, nil, nil, nil, 0x0116fddd, nil, nil, nil, nil, ".mmmm" },
  [6130] = { "Potere sul veleno", nil, nil, nil, nil, 0xfaefb521, nil, nil, nil, nil, ".mmmm" },
  [6132] = { "Tiratemi fuori di qui!", "Scorta Melizza Brimbuzzle, poi parla con Hornizz Brimbuzzle al Kodo Graveyard, a Desolace.", "Tiratemi fuori di qui!\n\nSono salita nella Valley of Spears per parlare con i Maraudine. Pensavo di poter fare qualche affare con loro... ma non vogliono parlare! Credo che vogliano mangiarmi!\n\nTirami fuori di qui e mio fratello Hornizz ti pagherà profumatamente! È al nostro accampamento vicino al cimitero dei kodo, a est.\n\nSbrighiamoci, {name}. Neanche due minuti fa ho sentito dei centauri parlare di prendere legna per la loro pentola...", "Hai visto mia sorella Melizza? È sempre in giro, e così finisce sempre nei guai.", "Mia sorella Melizza ha detto che saresti <venuto/venuta>. Grazie mille per averla tirata fuori dal pasticcio in cui si trovava; peccato che probabilmente si sia già cacciata in uno nuovo!", 0x6d185bdb, 0x31688590, 0x4440fa0b, 0x7e758e1f, 0xc3f8b2ba, "....." },
  [6134] = { "La raccolta del Ghost-o-plasm", "Porta 8 Ghost-o-plasms e la Crate of Ghost Magnets a Hornizz Brimbuzzle, a Desolace.", "C'è una valle a sud-est, la Valley of Bones, infestata dai fantasmi dei Magram. Fa paura, vero? Beh, pensa quanta paura fa ai Magram! Se catturassimo l'energia spettrale di quel posto, scommetto che varrebbe un sacco per quei centauri.\n\nEcco, prendi questa cassa di magneti per fantasmi. Se ne metti uno tra i due grandi scheletri della valle, i Dead Goliaths, i fantasmi ci si avvicineranno. Tieniti a distanza, elimina i fantasmi e prendi il loro ghost-o-plasm: è quello che venderemo ai Magram.", "Dov'è il mio ghost-o-plasm, {name}?", "Eccolo! Sembra che te ne sia finito un po' addosso. Un po' viscido, eh?\n\nBeh, grazie mille per tutto il disturbo, {name}. Questa roba varrà una fortuna... se riesco a convincere i centauri di cosa sia!", 0x417173f4, 0x0fee26ad, 0x25e62823, 0x5e12b43b, 0x7fb9819e, "....." },
  [6141] = { nil, "Parla con il Brother Anton, a Desolace.", "Il mio fratello d'armi, il Brother Anton, ha sentito voci di un'infestazione di non morti nella lontana Kalimdor, in una terra nota come Desolace. Anton ha subito prenotato un passaggio per quel luogo, per cercare e distruggere la minaccia dei non morti!\n\nCerca persone dotate di coraggio e risolutezza che lo aiutino. Se il tuo cuore è sincero, parla con Anton. Si trova a Desolace, nella città dell'Alliance di Nijel's Point.", nil, "Ho ricevuto notizia di aiuti in arrivo da est. Sei tu l'origine di queste voci? Sei qui per aiutare lo Scarlet Brother nella sua crociata?\n\nSe sì, ascolta bene...", nil, 0x56ae9363, 0x614b91fc, nil, 0xdede434a, "m..m." },
  [6161] = { "Reclama il tesoro di Rackmore!", "Trova la Rackmore's Silver Key. Trova la Rackmore's Golden Key. Trova e apri il Rackmore's Chest.", "Il diario di bordo di Rackmore racconta come la sua nave fosse diretta a Feathermoon Stronghold quando fu attaccata da creature marine. Per evitare che il suo tesoro cadesse in mani nemiche, nascose il suo forziere sulla Ranazjar Isle.\n\nPer aprire il forziere servono due chiavi, una d'argento e una d'oro. Queste chiavi sono andate perdute, ma se si trovano le chiavi e il forziere, ti attende un tesoro!", "Questo forziere è chiuso a chiave saldamente.", "Il forziere si apre rivelando il tesoro di Rackmore!", 0x9e9779af, 0x0255b29e, 0xb6b2aff5, 0x24ee971a, 0xa231516f, "....." },
  [6181] = { "Un messaggio rapido", "Porta la Lewis' Note a Thor, il maestro dei grifoni.", "Anche se da Stormwind non riceviamo molti aiuti diretti, ho un contatto in città che ci aiuta a rifornirci di armature. Si chiama Osric Strang. La sua bottega, Limited Immunity, è nella Old Town di Stormwind.\n\nLe nostre scorte di armature si assottigliano, e devo chiedere a Osric di mandarcene altre. Puoi portargli questo biglietto?\n\nIl modo più rapido per arrivare a Stormwind è Thor, il nostro maestro dei grifoni. È appena giù per la collina: portagli il mio biglietto, poi prendi un grifone per Stormwind.", "Sembri <uno/una> che va di fretta. Be', allora sei nel posto giusto!", "Devi portare questo biglietto a Stormwind? Nessun problema, puoi prendere uno dei miei grifoni!", 0xd0027ff1, 0xacee0705, 0x971b5160, 0x5c4d4ffe, 0x13821bcd, "....." },
  [6182] = { "Il primo e l'ultimo", "Parla con Mathias Shaw a Old Town, Stormwind. Risiede nelle Barracks.", "Nathanos Marris fu il primo e l'ultimo dei signori dei ranger umani. Un discepolo di Sylvanas Windrunner, ora la Banshee Queen dei Forsaken.\n\nCredevamo che Nathanos fosse caduto in combattimento durante la difesa di Lordaeron, cinque anni fa. Anche se il suo corpo non fu mai ritrovato, si presumeva che non fosse uscito vivo dalle Eastern Plaguelands.\n\nMathias Shaw sta indagando sulla scomparsa e potrebbe avere nuove informazioni. Presentati subito da lui. Risiede a Old Town, nelle Barracks.", nil, "Dopo alcune segnalazioni di insolite attività dei Forsaken nelle Eastern Plaguelands, sono stati inviati agenti dello SI:7 a indagare. I risultati di quell'indagine sono inquietanti.", 0x79d07d7d, 0x896b2154, 0xf98d351b, nil, 0xe83b7f3e, "...m." },
  [6183] = { "Onorare i morti", "Parla di nuovo con Mathias Shaw se vuoi accettare il suo incarico.", "Cinque dei miei migliori agenti sul campo furono assegnati al caso Marris. Uno tornò, solo per morire nel sonno tre giorni dopo.\n\nLe poche informazioni che riuscimmo a ricavare da lui erano farneticazioni incoerenti. Capimmo solo due parole: \"Nathanos\" e \"Blightcaller\".\n\nNon ho uomini a disposizione per proseguire questa indagine e Ravenholdt non ci aiuterà. Dobbiamo andare fino in fondo, se non altro per dare pace alle famiglie dei defunti. Mi aiuterai?", nil, "<Mathias annuisce.>\n\nAvevo fiducia che Bolvar mi avrebbe mandato uomini e donne d'onore: i soldati più devoti dell'Alliance.", 0xabd1351c, 0x4ac23430, 0x0f11aa78, nil, 0x4bc4d491, "...m." },
  [6184] = { nil, "Recati al Chillwind Camp, nelle Western Plaguelands, e incontra il tuo contatto, Flint Shadowmore.", "L'unica informazione che abbiamo finora, quindi, è che Nathanos Marris potrebbe essere stato ucciso da questo Blightcaller. Presumiamo che il Blightcaller sia lo stesso demonio che ha eliminato i miei agenti.\n\nFlint Shadowmore, un altro agente dello SI:7, è di stanza all'accampamento dell'Alliance di Chillwind Point, nelle Western Plaguelands. Cercalo: ti informerà sulla situazione attuale nelle Plagues e ti darà un incarico.\n\nBuona fortuna, {name}.", nil, "La prima missione sarà semplice, {name}. Entri ed esci. Ricognizione...", nil, 0xe649a5a0, 0xe08ff202, nil, 0x227d8a04, "m..m." },
  [6187] = { "L'ordine va ristabilito", "Raduna un esercito e recati nelle Eastern Plaguelands. Lancia un assalto in piena regola contro Nathanos Blightcaller e qualsiasi feccia dell'Horde che cerchi di proteggerlo.\n\nMantieni la lucidità, {name}. L'Horde difenderà il signore dei ranger a costo della vita.", "Sai quanti signori dei ranger esistono in questo mondo? Quanti signori dei ranger umani siano mai esistiti?\n\nLe imprese di Nathanos furono senza precedenti. Era un genio tattico, responsabile delle vittorie dell'Alliance in un decennio di conflitti.\n\nE ora... il campione dei Forsaken.\n\nNo. Non può essere. L'ordine va ristabilito.\n\nRaduna un esercito, {name}. Torna nelle Plagues con il tuo esercito e distruggi il Blightcaller.\n\nTi auguro buona fortuna, {name}. Ne avrai davvero bisogno per questa battaglia.", "<L'Highlord Bolvar Fordragon è immerso nei suoi pensieri.>", "È una tragedia. Penso... credo che la nostra specie sia maledetta, {name}. Siamo condannati a perdere i nostri più grandi guerrieri, i nostri eroi più nobili, i nostri studiosi più dotati.\n\nTi siamo debitori e ti assicuro, {name}, che ovunque si trovi ora Nathanos Marris, ti sorride dall'alto.", 0xa805e50b, 0xc706a84e, 0x37c61b0a, 0x3462e28c, 0x86761e86, "....." },
  [6261] = { nil, "Porta l'Osric's Crate a Dungar Longdrink, il maestro dei grifoni.", "{name}, ho raccolto in questa cassa tutto ciò che Lewis ha chiesto. Puoi portargliela?\n\nSe hai già parlato con Thor a Westfall, puoi prendere un grifone fino da lui. Dungar Longdrink è il nostro maestro dei grifoni, laggiù nel Trade District.\n\nParla con Dungar, poi porta questa cassa a Lewis il più in fretta possibile. Non vogliamo che i nostri combattenti a Westfall restino senza equipaggiamento nuovo!", "È sudore quello sulla tua fronte, <ragazzo/signora>? Hai corso troppo. La prossima volta prendi un grifone!", "Una cassa per Westfall, eh? Sei già <stato/stata> a Westfall? Se sì, nessun problema, amico mio. Ho molti grifoni addestrati a volare su quella rotta!", nil, 0x7f71eb16, 0x150a7f07, 0xd7a18628, 0xfce80486, "m....", nil, nil, nil, 0x276c0f6b, nil },
  [6281] = { "Proseguire per Stormwind", "Compra un volo in grifone dal maestro dei grifoni Thor, poi porta la Lewis' Note a Osric Strang, nella bottega Limited Immunity, nella Old Town di Stormwind.", "Per una piccola somma puoi prendere un grifone per Stormwind, così potrai consegnare il biglietto di Lewis a Osric. In nessun altro modo arriverai prima.\n\nSe ti sta bene, parlami di nuovo quando sei <pronto/pronta> per il volo. Ti chiederò qualcosa, ma fidati: ne varrà la pena!", "Sei in viaggio, eh? Sei <stato/stata> in qualche posto interessante?", "Ah, un biglietto da Quartermaster Lewis? Non mi stupisce che gli serva altra attrezzatura. Sentinel Hill è lontana, in una terra che Stormwind ha quasi dimenticato.\n\nBe', grazie, {name}. Ecco un po' di denaro per coprire le spese di viaggio.", 0x950eaddd, 0x9a2be79a, 0xd7241ffb, 0xd55888b8, 0x83dfa7ed, "....." },
  [6285] = { "Ritorno da Lewis", "Compra un volo in grifone per Sentinel Hill dal maestro dei grifoni Dungar Longdrink, poi porta l'Osric's Crate a Lewis, a Sentinel Hill.", "Il maestro dei grifoni a Westfall è Thor. Se gli hai già parlato, puoi prendere uno dei miei grifoni fino da lui.\n\nÈ una buona lezione da sapere: i grifoni sono sempre addestrati a volare verso la loro capitale, ma ti porteranno da un maestro dei grifoni lontano solo dopo che ci sarai già <stato/stata>.\n\nSei già <stato/stata> da Thor, quindi parla di nuovo con me quando sarai <pronto/pronta> a prendere un grifone per Westfall. Una volta lì, potrai consegnare l'Osric's Crate al Quartermaster Lewis.", "Sei <tornato/tornata> da Stormwind? Osric ha mandato l'armatura?", "Ottimo, hai portato l'armatura! La distribuiremo subito a chi ne ha bisogno.\n\nGrazie, {name}. I tuoi sforzi ci sono stati di grande aiuto. E ora che i grifoni non ti sono più estranei, spero che verrai spesso a dare il tuo aiuto a Sentinel Hill!", 0x96f66445, 0x1c7c566e, 0xb428ac6f, 0x54a54947, 0xb877172b, "....." },
  [6341] = { "I doni di Teldrassil", "Porta la Nessa's Collection a Vesprystus.", "I pescatori del villaggio di Rut'theran se la cavano molto bene, perché qui i pesci sono enormi e abbondanti. Vorrei confrontare i doni di questo posto con quelli della terraferma.\n\nHo una collezione di lische e scaglie di pesce che vorrei far arrivare a un mio collega a Darkshore. Si chiama Laird ed è un pescivendolo del villaggio di Auberdine.\n\nPorta la mia collezione al nostro maestro degli ippogrifi, Vesprystus, e parlagli del viaggio verso Auberdine.", "Come posso aiutarti? Ti serve un passaggio?", "Ah, vuoi portarlo ad Auberdine? Molto bene...", 0xfdaa45cb, 0x849cfb5d, 0xeffe6b5d, 0x2fd3c26c, 0x82c592b4, "....." },
  [6342] = { "In volo verso Auberdine", "Vola su un ippogrifo fino ad Auberdine con il maestro degli ippogrifi Vesprystus, poi porta la Nessa's Collection a Laird.", "Da Rut'theran ci sono due modi per andare ad Auberdine: in traghetto e in ippogrifo. Sono entrambi rapidi e affidabili, ma se non hai ancora volato ad Auberdine in ippogrifo, ti consiglio di farlo.\n\nÈ un buon consiglio parlare con il maestro degli ippogrifi in ogni città che ne ha uno. Una volta che gli hai parlato, potrai volare lì anche da altre città.\n\nEcco la collezione di Nessa. Parlami di nuovo quando sarai <pronto/pronta> a volare ad Auberdine e a consegnare la collezione di Nessa a Laird.", "Vieni da Teldrassil? Dimmi, com'è la pesca laggiù?", "Un pacco da Nessa? Grazie, {name}! Mi aveva detto che mi avrebbe mandato dei campioni dei pesci pescati vicino al villaggio di Rut'theran. Pensa che potrebbero essere molto diversi da quelli pescati qui...\n\nAccidenti! Questa mascella è grande quasi il doppio di quella dello stesso pesce che si trova qui. E queste scaglie sono grandi come un pugno chiuso! Incredibile!", 0xdcb4055c, 0xedfc0608, 0xf7020ff1, 0x289d443c, 0xa33b905a, "....." },
  [6343] = { "Ritorno da Nessa", "Porta la Laird's Response a Nessa Shadowsong.", "Devo mandare una risposta a Nessa. Le interesserà molto sapere quanto sono diversi i pesci di qui da quelli lungo la costa di Teldrassil. Possiamo solo fare ipotesi sulla causa, ma sospetto che sia l'albero del mondo stesso a influire sulla fauna intorno a lui!\n\nTi prego, porta questa risposta a Nessa. Se vuoi tornare a Rut'theran in ippogrifo, parla con il maestro degli ippogrifi Caylais Moonfeather. Se vuoi prendere il traghetto, ne parte uno regolarmente dal molo a nord-ovest.", "{name}, sei <tornato/tornata> da Auberdine? Hai parlato con Laird?", "Molto interessante. I pesci qui sono grandi, ma non pensavo che la differenza di abbondanza tra qui e il continente fosse così grande. Deve esserci un motivo...\n\nBeh, grazie, {name}. Discuterò con gli abitanti del villaggio delle notizie che hai portato. Forse un giorno troveremo l'origine di questa stranezza. Ma fino ad allora ne raccoglieremo i benefici!", 0xba10c9cf, 0x9efa6697, 0x2381f0ae, 0x47a9c3c4, 0x4e30b81a, "....." },
  [6344] = { nil, "Parla con Nessa Shadowsong.", "Una mia amica, Nessa Shadowsong, è una mercante di pesce del villaggio di Rut'theran. Deve far arrivare un pacco a Darkshore e cerca qualcuno che la aiuti.\n\nSe ti interessa, per raggiungere Nessa devi prendere il portale di Darnassus per Rut'theran Village. Trovi il portale a ovest dei Temple Gardens.", nil, "Sì, mi serve un corriere che porti un pacco a Darkshore. Mi aiuterai?", nil, 0x0db93fa5, 0x3d0373e4, nil, 0xaae17e8e, "m..m." },
  [6387] = { "Studenti d'onore", "Porta la Brock's List a Thorgrum Borrelson, a Thelsamar.", "Vedo molti giovani nani alla mia porta, ansiosi di imparare il mestiere del minatore. E se c'è una cosa di cui un minatore ha bisogno più di ogni altra, è un piccone!\n\nHo un elenco di studenti di estrazione che hanno ottenuto voti alti nelle lezioni e si sono meritati un piccone d'onore. Porta il mio elenco a Golnir Bouldertoe, a Ironforge. Lui preparerà i picconi.\n\nIl modo più rapido per arrivare a Ironforge è in grifone, quindi porta l'elenco al nostro maestro dei grifoni, Thorgrum Borrelson, e parlagli del trasporto per Ironforge.", "Ne hai già abbastanza di Thelsamar? Sei <pronto/pronta> a partire per un'altra città?", "Devi portarlo a Ironforge, eh? Per una piccola somma posso metterti in groppa a uno dei miei grifoni, e ti porterà là. Che ne dici?", 0x24e749d7, 0xf62403c1, 0x57e23adf, 0x093769d9, 0xedf1dc2f, "....." },
  [6388] = { nil, "Porta gli Honorary Picks a Gryth Thurden, a Ironforge.", "Ecco i picconi onorari per gli allievi di Brock. Se sei già <stato/stata> a Thelsamar, dovresti tornarci in grifone!\n\nPorta i picconi al nostro maestro dei grifoni, Gryth Thurden, e parlagli di un volo per tornare a Thelsamar.", "Sembri avere un posto dove andare. Ti serve uno dei miei grifoni?", "Devi portarli a Thelsamar, eh? Nessun problema. Purché tu sia già <stato/stata> a Thelsamar e abbia parlato con Thorgrum Borrelson, puoi prendere uno dei miei grifoni per tornare da lui.", nil, 0x029c72cb, 0xc7801ddb, 0x4e09c9af, 0x721a7bfa, "m...." },
  [6391] = { "In volo verso Ironforge", "Compra un volo in grifone per Ironforge dal maestro dei grifoni Thorgrum Borrelson, poi porta la Brock's List a Golnir Bouldertoe, a Ironforge.", "Per poche monete, uno dei miei grifoni ti porterà a Ironforge. Da lì, consegna la lista di Brock a Golnir Bouldertoe. Lo troverai nella Deep Mountain Mining Guild. Si trova nel Great Forge District di Ironforge, proprio dove ti lascerà il mio grifone!\n\nParlami di nuovo quando sarai <pronto/pronta> per il viaggio.", "Cosa posso fare per voi, <signore/signora>?", "Ah, l'ultima lista dei migliori allievi di Brock. Ho un lotto di picconi onorari pronti. Devo solo incidere i nomi degli studenti...", 0xd28081ed, 0x0477c979, 0x2cfa2e26, 0x92c650dc, 0xe778e783, ".....", nil, nil, nil, 0xd6deda79, nil },
  [6392] = { "Ritorno da Brock", "Compra un volo in grifone per Thelsamar dal maestro dei grifoni Gryth Thurden, poi porta gli Honorary Picks a Brock Stoneseeker, a Thelsamar.", "Per una piccola somma puoi comprare un volo in grifone per Thelsamar... purché tu ci sia già <stato/stata>. I grifoni ti portano solo nei posti dove sei già <stato/stata>, quindi assicurati di parlare con ogni maestro dei grifoni che incontri, così potrai volare da lui in seguito.\n\nSei già <stato/stata> da Thorgrum, il maestro dei grifoni di Thelsamar, quindi ora puoi tornare da lui. E una volta a Thelsamar, potrai consegnare i picconi a Brock Stoneseeker.\n\nParlami quando sei <pronto/pronta> a partire.", "Ah, {name}. Sei <tornato/tornata> da Ironforge?", "Hai portato i picconi. Ottimo! Li darò ai miei allievi minatori. Sono sicuro che non vedono l'ora di usarli sui giacimenti di Loch Modan.\n\nGrazie per il tuo aiuto, {name}. Sono in debito con te, ma spero che questo denaro copra almeno le spese di viaggio.", 0xe9291a93, 0xd370798c, 0x72505319, 0x7b4723d5, 0xf9547062, "....." },
  [6403] = { "La grande mascherata", "Segui Reginald Windsor per Stormwind. Proteggilo da ogni pericolo!", "È stata proprio un'avventura, amico. Ti devo un grande debito di gratitudine. Forse, quando tutto sarà finito...\n\nCome avrai certamente capito ormai, Lady Prestor è Onyxia: progenie di Deathwing, gemella del tiranno dello Spire, Nefarian.\n\nPer troppo tempo ha tenuto il nostro regno sotto il suo sguardo ammaliatore. Persino l'Highlord è controllato dal suo inganno: una marionetta. Oggi finisce tutto... L'incantesimo sarà spezzato.\n\nNon preoccuparti, perché insieme vinceremo!\n\nSei <pronto/pronta>?", "Io... io... ero impotente.", "<Bolvar stringe il medaglione infranto.>\n\nLa magia che contiene deve essere riaccesa. Il dragon's eye deve essere sintonizzato.\n\nIl sacrificio di Windsor ha liberato il nostro regno, ma la minaccia di Onyxia e della sua stirpe incombe sempre.\n\nQuesto medaglione è ciò che teneva prigionieri la mia mente e il mio corpo. È anche ciò che mi dava accesso alla mente stessa di Onyxia, ai suoi segreti. Anche se ora le visioni sono confuse, alcune cose le ricordo.", 0x21125223, 0x83f7ff7b, 0x5c12f001, 0x98e54ef8, 0x76253855, "....." },
  [6501] = { "Il Dragon's Eye", "Devi cercare in tutto il mondo un essere capace di restituire il potere al Fragment of the Dragon's Eye. L'unica informazione che possiedi su un tale essere è che esiste.", "Un frammento del medaglione infranto è tutto ciò che posso offrirti.\n\nDevi trovare qualcun altro del sangue dei draghi disposto ad aiutarti a forgiare una nuova chiave. Una volta ottenuta questa chiave, dovrai recarti al Wyrmbog, nel Dustwallow Marsh. È lì che troverai la sua tana, {name}.\n\nDove trovare altri stormi disposti ad aiutare? Purtroppo non lo so... Si dice che esistano. Alcuni potrebbero persino lavorare e vivere tra noi, travestiti da una delle razze umanoidi. Ti auguro buona fortuna.", "Sento un'aura malvagia irradiarsi da te, {race}. Cosa potresti avere che emana un'aura simile?", "Avrei dovuto saperlo: un pezzo della madre della progenie dei draghi neri, Onyxia. Che ripugnanza...", 0x667cb580, 0xc8568b34, 0x01f50423, 0x28f8fcf6, 0xb8659b7f, "....." },
  [6561] = { "Malvagità a Blackfathom", nil, nil, nil, nil, 0x43ec82c9, nil, nil, nil, nil, ".mmmm" },
  [6626] = { "Un'orda di malvagi", "Uccidi 8 Razorfen Battleguard, 8 Razorfen Thornweaver e 8 Death's Head Cultist e torna da Myriam Moonsinger, vicino all'ingresso di Razorfen Downs.", "Da quel che ho visto, i Forsaken non trasmettono la loro... malattia. Questo diplomatico sembra concedere la non morte ai suoi aspiranti seguaci. Comincio a pensare che sia uno della Scourge.\n\nPer ora, però, non mi preoccupa lui, ma le schiere crescenti intorno a lui. Strisciano fuori dall'ombra ogni giorno, quasi implorandolo di dar loro più potere.\n\nNon sono abbastanza potente da affrontarli da sola, {name}. Che ne dici? Te la senti di andare a caccia?", "Come va la caccia, {name}? Vedere anche solo questo piccolo saggio del potere di questo diplomatico mi toglie ogni dubbio: la Scourge è una delle più grandi minacce che questo mondo abbia mai visto.", "Grazie, {name}! Il lavoro che hai fatto sarà di grande aiuto, ne sono certa.\n\nContinuerò a studiare questo diplomatico e il resto dei quilboar qui. Se cerchi avventure più grandi, troverei qualche amico e andrei nella grotta che sembra le fauci di un grande cinghiale, proprio laggiù. Sono sicura che una volta dentro troverai sfide più grandi da affrontare.", 0xa6ad637c, 0x78151438, 0x50ddd7c3, 0x416675bc, 0x196700d7, "....." },
  [6721] = { "La via del cacciatore", "Parla con Dazalar, a Dolanaar.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Dazalar, a Dolanaar. Lui può metterti sulla strada per guadagnarti un animale tutto tuo.", nil, "Sì, è il momento, {class}.", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0xca92f25f, "...m." },
  [6722] = { "La via del cacciatore", "Parla con Dazalar, a Dolanaar.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Dazalar, a Dolanaar. Lui può metterti sulla strada per guadagnarti un animale tutto tuo.", nil, "Sì, è tempo di addestrarti...", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0x6d03693e, "...m." },
  [6761] = { "La nuova frontiera", "Parla con Mathrengyl Bearwalker, nel Cenarion Enclave di Darnassus.", "Ho affidato al mio secondo, Mathrengyl Bearwalker, la richiesta di aiuto di Moonglade. Parlane con lui, non con me.\n\nLascia che ti dia un consiglio... amichevole. Sono io che ci ho guidati fuori dalle tenebre, non il Cenarion Circle di Moonglade, quando per la nostra razza tutto era perduto. Teldrassil ci dà a tutti una nuova vita! Loro vorrebbero farti credere il contrario, e credere alla loro propaganda sarebbe da sciocchi.\n\nLascio a te decidere se sei <uno/una> <sciocco/sciocca> o no.", nil, "Sì {class}, grazie per essere <venuto/venuta>. Mi scuso per il malinteso... l'aria è densa di sfiducia tra l'arcidruido qui e Keeper Remulos a Moonglade. Ciascuno sospetta l'altro di imbrogli, e il fatto che le strane corruzioni di Teldrassil continuino senza sosta resta un problema. Non aiuta certo a placare la sfiducia.\n\nComunque sia, il nostro dovere verso il Cenarion Circle resta... anche se chi lo guida può non essere d'accordo.", 0x980efd04, 0xc843270f, 0x3b0ebeda, nil, 0x1a73fafa, "...m." },
  [6762] = { nil, "Parla con Rabine Saturna nel villaggio di Nighthaven, a Moonglade. Moonglade si trova tra Felwood e Winterspring, raggiungibile con un sentiero che parte dalla Timbermaw Hold.", "Per questo compito, il maggiordomo di Keeper Remulos a Moonglade, Rabine Saturna, cerca aiuto per esplorare le vaste terre desolate molto a ovest di Tanaris... e ancora più a ovest di Un'Goro. Dovresti trovarlo a Nighthaven, il villaggio principale di Moonglade.\n\nAnche se il tuo lavoro sarà senza dubbio di enorme beneficio per tutti noi, ti consiglio di muoverti con cautela. Ci sono tensioni tra Darnassus e Moonglade... tensioni che col tempo potrebbero crescere.", nil, "Sono Rabine Saturna, e a nome di Keeper Remulos e di tutti gli abitanti di questa radura sacra ti do il benvenuto.\n\nApprezzo il tuo interesse e la tua voglia di aiutare il Cenarion Circle. So anche che l'arcidruido di Darnassus ti ha espresso il suo disappunto per l'aiuto che ci dai. Puoi stare <tranquillo/tranquilla>: è per il bene comune, e sarai al sicuro da qualunque ritorsione sconsiderata di cui potresti essere bersaglio.\n\nQui sei tra amici, {name}.", nil, 0x2d1faec5, 0xf45142aa, nil, 0xbe6728af, "m..m." },
  [6845] = { "Svelare i segreti del passato", "Parla con Rabine Saturna nel villaggio di Nighthaven, a Moonglade.", "Comunque, dovresti ripassare da me abbastanza presto... sempre che tu voglia sapere cosa c'era qui dentro. Appena scoprirò di cosa si tratta, e se è davvero un libro, sarò felice di condividere quelle informazioni con te.\n\nNel frattempo, io passerei dalla madre della tana di questo piccolo accampamento di orsi, Rabine. Di sicuro vorrà sapere che follie hai combinato. Non far mai aspettare la madre della tana, {name}... a meno che tu non voglia essere <ricoperto/ricoperta> di miele.\n\nÈ già successo, fidati.", nil, "Ah, {name}, speravo che saresti <passato/passata>. Sono lieto di vederti in salute.\n\nMi è stato detto che saresti <rientrato/rientrata> dal campo, e volevo esprimerti personalmente la gratitudine del Cenarion Circle per l'aiuto che ci hai dato finora. Senza dubbio ci sono altri segreti da svelare a Silithus; ciò che hai consegnato a Umber dovrebbe rivelarsi molto interessante una volta decifrato. Ti prego, accetta questo come segno del nostro continuo apprezzamento per il tuo aiuto.\n\nGrazie, {class} dal cuore generoso.", 0xeabb3200, 0x5071bbe4, 0x9bb68a79, nil, 0xa03acc7f, "...m." },
  [6961] = { nil, nil, nil, nil, "Oh oh oh, salve. Sono il Greatfather Winter e, per gentile concessione della brava gente di Smokywood Pastures... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina di Smokywood Pastures\"... desidero augurarti un fantastico Feast of Winter Veil.\n\nSe quest'anno sei <stato/stata> <buono/buona>, forse riceverai i dolcetti di Smokywood Pastures come regalo per il Feast of Winter Veil. Evviva.", nil, nil, nil, nil, 0x296b27e3, "mmmm." },
  [6962] = { nil, nil, "Ehi, puoi fare un favore a Greatfather Winter, ehm, <piccolo/piccola> mio?\n\nNon per parlare di me in terza persona senza motivo, ma Greatfather Winter è all'opera da tutto il giorno e gli farebbe bene un dolcetto. Qualche biscotto di pan di zenzero e del latte ghiacciato per mandarli giù sarebbero proprio l'ideale. Pensi di poter essere un amico per il Greatfather e procurarmene un po'?", "Tutto questo parlare di dolcetti mi ha fatto venire voglia. Mmmm... biscotti di pan di zenzero e latte...", "Sei proprio un bell'aiutante per il vecchio Greatfather Winter, {name}. Buona Feast of Winter Veil.\n\nEcco un pensierino... sai, per l'impegno.", nil, nil, 0xd3822e00, 0x11c73f24, 0x004980cd, "mm...", nil, nil, 0xcc6e16c8, nil, nil },
  [6981] = { nil, "Recati a Ratchet per trovare qualcuno che possa dirti di più sul frammento luminoso.\n\nPoi consegna il frammento come ti verrà indicato.", "Il frammento è di un verde brillante e, sebbene solido, sotto la superficie sembra vorticare del fumo. Non puoi fare a meno di fissare le profondità del cristallo; al tempo stesso, sai che c'è qualcosa di molto inquietante in esso.\n\nForse dovresti vedere se qualcuno a Ratchet può dirti di più su questo strano frammento.", "Salve, {race}. Cosa posso fare per te?", "Oh... non ho mai visto niente del genere...", nil, 0x9db6d7f4, 0xf1eddfb4, 0x60aba222, 0xcb5cd7b9, "m...." },
})
